package p3q

// Frozen FIPS 204 known-answer vectors for the remaining two P3Q
// parameter sets. The ML-DSA-44 vector lives in kat_test.go; these
// extend the same discipline to ML-DSA-65 (the Lux production target)
// and ML-DSA-87, so no parameter set is covered only by a round trip
// that checks the implementation against itself.
//
// Each set carries THREE blobs. katNNPub and katNNSig are a signature
// over katExtMsg under this precompile's own context, PrecompileCtx
// ("lux-evm-precompile-p3q-v1"), and must verify. katNNForeignSig is a
// signature by the SAME key over the SAME message under the SIBLING
// slot's context ("lux-evm-precompile-pulsar-v1", precompile 0x012204)
// and must NOT verify here. That third blob is what makes the
// domain-separation claim testable against a genuine signature instead
// of a corrupted one: without context binding it would be replayable
// from 0x012204 to 0x012205 verbatim.
//
// Provenance: mldsa.GenerateKey + SignCtx, self-checked in both
// directions at generation time.
const (
	katExtMsgHex = "a0a1a2a3a4a5a6a7a8a9aaabacadaeafb0b1b2b3b4b5b6b7b8b9babbbcbdbebf"

	kat65PubHex = ""

	kat65SigHex = ""

	kat65ForeignSigHex = ""

	kat87PubHex = ""

	kat87SigHex = ""

	kat87ForeignSigHex = ""
)
